  "italian::focaccia": { en: "Focaccia is a flat, oven-baked Italian bread, similar to pizza dough, often dimpled and seasoned with olive oil, originating from ancient Rome.", source: "Wikipedia" },
  "italian::gelato": { en: "Gelato is a dense Italian frozen dessert made with milk, sugar, and flavorings, churned slowly with less air than ice cream.", source: "Wikipedia" },
  "italian::gnocchi": { en: "Gnocchi are soft Italian dumplings traditionally made from potato, flour, and egg, often served with a sauce.", source: "Wikipedia" },
