  "italian::panna cotta": { en: "Panna cotta is an Italian dessert of sweetened cream thickened with gelatin and molded, traditionally from Piedmont.", source: "Wikipedia" },
  "italian::parmigiana di melanzane": { en: "Parmigiana di melanzane is a baked Italian casserole of fried eggplant slices layered with tomato sauce and mozzarella cheese.", source: "Wikipedia" },
  "italian::pasta alla gricia": { en: "Pasta alla gricia is a pasta dish from Lazio, Italy, prepared with guanciale, Pecorino Romano cheese, and black pepper.", source: "Wikipedia" },
  "italian::pasta amatriciana": { en: "Pasta amatriciana is a pasta dish from Amatrice, Lazio, made with guanciale, Pecorino Romano cheese, and tomato sauce.", source: "Mezzogiorno" },
  "italian::pizza margherita": { en: "Pizza Margherita is a Neapolitan pizza topped with tomatoes, mozzarella, and basil, whose colors represent the Italian flag.", source: "Wikipedia" },
  "italian::pizza marinara": { en: "Pizza Marinara is the oldest Neapolitan pizza, topped with tomatoes, garlic, oregano, and olive oil, traditionally made without cheese.", source: "Wikipedia" },
  "italian::prosciutto e melone": { en: "Prosciutto e melone is an Italian appetizer featuring thin slices of cured ham served with fresh melon.", source: "Wikipedia" },
  "italian::ravioli": { en: "Ravioli are a type of Italian pasta consisting of small, filled envelopes of dough, often with cheese or meat.", source: "Wikipedia" },
  "italian::risotto ai funghi": { en: "Risotto ai funghi is a traditional Italian risotto made with short-grain rice, various mushrooms, and Parmigiano-Reggiano cheese.", source: "Savas Kitchen" },
  "italian::risotto alla milanese": { en: "Risotto alla milanese is a classic dish from Milan, Italy, characterized by its golden color from saffron and creamy Arborio rice.", source: "Italy Segreta" },
  "italian::saltimbocca": { en: "Saltimbocca is a Roman dish of pan-fried veal cutlets topped with prosciutto and sage, whose name means \"jumps in the mouth.\"", source: "Grico's" },
  "italian::spaghetti aglio e olio": { en: "Spaghetti aglio e olio is a pasta dish from Naples, Italy, made by tossing spaghetti with garlic sautéed in olive oil.", source: "Wikipedia" },
