  "peranakan::itek tim": { en: "Itek tim is a Peranakan salted vegetable duck soup, featuring duck simmered with kiam chye (salted mustard greens) and often tamarind for a sour broth.", source: "Cookidoo® – the official Thermomix® recipe platform" },
  "peranakan::kueh ambon": { en: "Kueh ambon is a cake from Medan, Indonesia, known for its honeycomb structure, caramel and coconut milk fragrance, and made with tapioca starch and eggs.", source: "saf-instant.asia" },
  "peranakan::kueh bahulu": { en: "Kueh bahulu is a traditional Malay egg sponge cake, made from eggs, flour, and sugar, often baked in decorative brass moulds.", source: "Rasa Malaysia" },
  "peranakan::kueh bingka ubi": { en: "Kueh bingka ubi is a Nyonya baked tapioca cake with a crispy golden top and a soft, chewy centre, made with grated tapioca, coconut milk, and eggs.", source: "Huang Kitchen" },
  "peranakan::kueh dadar": { en: "Kueh dadar is a rolled crepe snack with a pandan-flavoured green crepe filled with grated coconut and gula melaka.", source: "Curious Cuisiniere" },
  "peranakan::kueh pie tee": { en: "Kueh pie tee is a Peranakan thin, crispy pastry tart shell filled with a spicy-sweet mixture of thinly sliced vegetables and prawns.", source: "Wikipedia" },
  "peranakan::kueh salat": { en: "Kueh salat is a two-layered Nyonya kueh featuring a glutinous rice base and a pandan coconut custard top.", source: "Shiokman Recipes" },
  "peranakan::lapis sagu": { en: "Lapis sagu is a multi-layered steamed sweet cake made with tapioca and rice flour, coconut milk, and vibrant alternating coloured layers.", source: "My Kitchen Produce" },
  "peranakan::nasi ulam": { en: "Nasi ulam is a traditional rice dish mixed with various finely chopped fresh herbs (ulam), often including flaked fish and toasted grated coconut.", source: "Wikipedia" },
  "peranakan::nyonya bak chang": { en: "Nyonya bak chang are Peranakan glutinous rice dumplings, often blue-tinted with butterfly pea flowers, filled with sweet-savory pork and candied winter melon.", source: "Beautiful Voyager" },
  "peranakan::nyonya curry chicken (kapitan)": { en: "Nyonya curry chicken (kapitan) is a Penang Peranakan chicken curry, known for its thicker, richer gravy and distinct blend of Southeast Asian spices.", source: "Wikipedia" },
