  "peranakan::nyonya rendang": { en: "Nyonya rendang is a Peranakan meat dish slow-cooked in coconut milk and a rich spice mix, often with a tangy flavour.", source: "Wikipedia" },
  "peranakan::perut ikan": { en: "Perut ikan is a Nyonya tamarind-based curry featuring a medley of aromatic herbs, vegetables, and often preserved fish stomach or prawns.", source: "Sujean's space" },
  "peranakan::pulut hitam": { en: "Pulut hitam is a black glutinous rice dessert, simmered into a creamy porridge with pandan-scented coconut milk and sweetened with gula melaka.", source: "Don Signature Crab" },
  "peranakan::pulut tai tai": { en: "Pulut tai tai is a Nyonya kuih of steamed glutinous rice, often tinted blue with butterfly pea flowers and served with kaya.", source: "Savour of Asia" },
  "sichuan::beggar's chicken": { en: "Beggar's chicken is a Chinese dish of chicken stuffed, wrapped in lotus leaves and clay, then baked slowly.", source: "Wikipedia" },
  "sichuan::boiled beef in chili oil (shui zhu niu rou)": { en: "Boiled beef in chili oil (shui zhu niu rou) is a Sichuan dish featuring tender beef slices cooked in a spicy, numbing broth with chili bean paste.", source: "PattyPlates" },
  "sichuan::boiled fish in chili oil (shui zhu yu)": { en: "Boiled fish in chili oil (shui zhu yu) is a Sichuan dish with thinly sliced fish poached in a fiery broth, topped with dried chilies and Sichuan peppercorns.", source: "Omnivore's Cookbook" },
  "sichuan::chao shou": { en: "Chao shou are Sichuan dumplings, typically filled with pork and ginger, and served in a spicy, sour, and tangy sauce, often with chili oil.", source: "Wikipedia" },
  "sichuan::chengdu dan dan noodles": { en: "Chengdu dan dan noodles are wheat noodles served with a spicy sauce, often containing pickled vegetables, chili oil, and minced pork.", source: "Wikipedia" },
  "sichuan::chongqing chicken (la zi ji)": { en: "Chongqing chicken (la zi ji) is a Sichuan stir-fry with deep-fried chicken pieces tossed with abundant dried red chilies and Sichuan peppercorns.", source: "Wikipedia" },
  "sichuan::chongqing hot pot": { en: "Chongqing hot pot is a spicy and numbing hot pot characterized by its beef tallow-based broth with chili peppers and Sichuan peppercorns.", source: "Wikipedia" },
  "sichuan::dan dan noodles": { en: "Dan dan noodles are a Sichuan dish of wheat noodles with minced pork and a spicy chili oil sauce, traditionally sold by street vendors.", source: "Coley Cooks" },
  "sichuan::fish-fragrant aubergine": { en: "Fish-fragrant aubergine is a Sichuan stir-fried eggplant dish prepared with \"fish-fragrant\" seasonings like pickled chilies, garlic, and ginger, containing no fish.", source: "Yogurtsoda" },
  "sichuan::fish-fragrant pork (yu xiang rou si)": { en: "Fish-fragrant pork (yu xiang rou si) is a Sichuan dish with shredded pork, featuring a sweet, sour, salty, and spicy flavor from seasonings, not fish.", source: "Travel China Guide" },
  "sichuan::husband and wife lung slices (fu qi fei pian)": { en: "Husband and wife lung slices (fu qi fei pian) is a cold Sichuan dish of sliced beef and offal in a chili-oil and peppercorn dressing, created by a Chengdu couple.", source: "Bistropedia" },
  "sichuan::kung pao chicken (gong bao ji ding)": { en: "Kung Pao chicken is a spicy, stir-fried Sichuan dish with diced chicken, peanuts, vegetables, chili peppers, and Sichuan peppercorns for a numbing flavor.", source: "Wikipedia" },
  "sichuan::ma la xiang guo": { en: "Ma la xiang guo is a customizable Sichuan dry pot dish where various ingredients are stir-fried in a rich, numbing, and spicy mala sauce.", source: "Wikipedia" },
  "sichuan::mala beef noodle": { en: "Mala beef noodle is a Sichuan dish featuring noodles and beef in a spicy and numbing broth or sauce, often with Sichuan peppercorns.", source: "Choochoo-ca-Chew" },
  "sichuan::mapo tofu": { en: "Mapo tofu is a Sichuan dish of soft tofu in a spicy, oily sauce with minced meat, douban, and Sichuan peppercorns, known for its \"mala\" flavor.", source: "Wikipedia" },
  "sichuan::mouthwatering chicken (kou shui ji)": { en: "Mouthwatering chicken (kou shui ji) is a cold Sichuan appetizer featuring poached chicken drenched in a spicy, savory, and numbing chili sauce.", source: "What To Cook Today" },
  "sichuan::pock-marked old woman tofu (mapo doufu alt)": { en: "Mapo doufu, or pock-marked old woman tofu, is a Sichuan dish of tofu and minced meat in a spicy, numbing sauce, created in 1862.", source: "TasteAtlas" },
  "sichuan::saliva chicken (kou shui ji) alt name": { en: "Saliva chicken (Kou Shui Ji) is a chilled Sichuan appetizer of poached chicken served in a spicy red oil sauce with Sichuan peppercorns.", source: "Omnivore's Cookbook" },
  "sichuan::sichuan cold noodle": { en: "Sichuan cold noodle is a street snack featuring chilled noodles tossed in a spicy, numbing, and aromatic chili oil dressing.", source: "Food52" },
  "sichuan::sichuan dry-fried green beans": { en: "Sichuan dry-fried green beans are blistered green beans often stir-fried with minced pork, preserved mustard greens, and chili.", source: "That Spicy Chick" },
  "sichuan::sichuan hot pot": { en: "Sichuan hot pot is a communal dish where raw ingredients are cooked in a numbingly hot and spicy mala broth with Sichuan peppercorns.", source: "TasteAtlas" },
  "sichuan::sichuan pickled mustard greens": { en: "Sichuan pickled mustard greens (zha cai) are fermented mustard plant stems from Chongqing, known for their spicy, sour, and salty taste.", source: "Wikipedia" },
  "sichuan::sichuan-style smoked duck (zhang cha ya)": { en: "Sichuan-style smoked duck (Zhang cha ya) is a traditional Sichuan dish, hot-smoked over tea leaves and camphor wood for its distinctive aroma.", source: "Wikipedia" },
  "sichuan::sichuan-style spicy crayfish": { en: "Sichuan-style spicy crayfish (xiao longxia) is a dish of crayfish stir-fried with numbing Sichuan peppercorns and chilies.", source: "The Food Dictator" },
  "sichuan::twice-cooked pork (hui guo rou)": { en: "Twice-cooked pork (hui guo rou) is a Sichuan dish of pork belly slices that are first simmered, then thinly sliced and stir-fried.", source: "Wikipedia" },
  "sichuan::zhong dumplings": { en: "Zhong dumplings are boiled pork dumplings from Chengdu, served in a distinctive sweet, spicy, and garlicky chili oil sauce.", source: "TasteAtlas" },
  "singaporean::100 plus (isotonic)": { en: "100PLUS is an isotonic sports drink manufactured by Fraser and Neave, launched in 1983 in Malaysia and Singapore to replenish electrolytes.", source: "Wikipedia" },
