  "singaporean::itek tim": { en: "Itek tim is a Peranakan salted vegetable duck soup, traditionally featuring duck, preserved mustard greens, and sour plum.", source: "NLB" },
  "singaporean::kaya": { en: "Kaya is a sweet, creamy spread or custard made from coconut cream, eggs, sugar, and pandan leaves, commonly eaten on toast.", source: "NLB" },
  "singaporean::kaya puff": { en: "Kaya puff is a sweet, flaky pastry filled with creamy kaya, a coconut jam commonly found in Southeast Asia.", source: "Beautiful Voyager Kitchen" },
  "singaporean::kaya toast": { en: "Kaya toast is a dish of toasted bread with butter and kaya (coconut jam), believed to be created by Hainanese immigrants in the 19th century.", source: "Wikipedia" },
