  "singaporean::kopi peng": { en: "Kopi peng is a Singaporean iced coffee typically made with condensed milk.", source: "Wikipedia; SingaporeCalorie" },
  "singaporean::kopi siu dai": { en: "Kopi siu dai is a Singaporean coffee made with condensed milk and less sugar.", source: "Wikipedia; CNA" },
