  "singaporean::kueh ko swee": { en: "Kueh ko swee is a steamed Nyonya cake made from tapioca and rice flour, sweetened with gula melaka and often served with grated coconut.", source: "Grokipedia" },
  "singaporean::kueh pie tee": { en: "Kueh pie tee is a Peranakan pastry tart shell filled with a spicy, sweet mixture of thinly sliced vegetables and prawns.", source: "Wikipedia" },
  "singaporean::kueh salat": { en: "Kueh salat is a two-layered Nyonya kueh featuring a sticky glutinous rice base and a smooth, aromatic pandan coconut custard top.", source: "Shiokman Recipes" },
