  "taiwanese::oyster omelette taiwan": { en: "Taiwanese oyster omelette is a street food made with small oysters, eggs, and sweet potato starch, pan-fried until crispy.", source: "Tiny Urban Kitchen" },
  "taiwanese::pineapple cake": { en: "Pineapple cake is a Taiwanese sweet pastry with a buttery crust and a jammy pineapple filling, often including winter melon.", source: "Wikipedia" },
  "taiwanese::popcorn chicken taiwan": { en: "Taiwanese popcorn chicken is bite-sized, double-fried chicken pieces seasoned with five-spice powder and white pepper, often served with fried basil.", source: "Wikipedia" },
  "taiwanese::scallion pancake": { en: "Scallion pancake is a savory Chinese flatbread, made with laminated dough and an oil-flour paste to create its characteristic flaky layers.", source: "The Kitchn" },
  "taiwanese::stinky tofu": { en: "Stinky tofu is a Chinese form of fermented tofu with a strong odor, traditionally made by fermenting tofu in a brine.", source: "Wikipedia" },
  "taiwanese::taiwan night market dishes": { en: "Taiwan night market dishes refer to a diverse array of street foods and snacks, including popcorn chicken and oyster omelets, found in bustling markets.", source: "Jetlag Jenna" },
  "taiwanese::taiwanese sausage": { en: "Taiwanese sausage is a plump, juicy pork sausage, sweet and savory, often grilled and served with raw garlic cloves.", source: "FoodMap" },
  "taiwanese::three cup chicken": { en: "Three cup chicken is a Taiwanese stir-fry named for its traditional equal parts of soy sauce, rice wine, and sesame oil.", source: "Cooking with Cocktail Rings" },
  "taiwanese::xiao long bao": { en: "Xiao long bao are Chinese soup dumplings traditionally prepared in a small bamboo steaming basket, known for their savory broth filling.", source: "Wikipedia" },
  "teochew::bak chor mee": { en: "Bak chor mee is a Singaporean Teochew dish of egg noodles tossed in a vinegary sauce with minced pork, pork slices, and often mushrooms.", source: "Singapore Global Network" },
  "teochew::beef kway teow soup": { en: "Teochew beef kway teow soup is a flat rice noodle soup featuring tender beef slices, offal, and a clear, savory broth often enhanced by preserved vegetables.", source: "Makansutra" },
  "teochew::cheng tng": { en: "Cheng tng is a light and refreshing Teochew dessert soup, often served hot or cold, containing ingredients like dried longan, ginkgo nuts, and white fungus.", source: "Makansutra" },
  "teochew::cold crab teochew-style": { en: "Cold crab Teochew-style is a dish of fresh crabs that are steamed and then served chilled, emphasizing their natural sweetness.", source: "Seaco Online" },
  "teochew::fish soup bee hoon": { en: "Fish soup bee hoon is a comforting soup with fish slices and rice vermicelli, often enriched with evaporated milk and ginger.", source: "Foodie Baker" },
  "teochew::fishball noodle": { en: "Fishball noodle is a Teochew dish with bouncy fish balls, fish cake, and noodles, served in a clear broth or tossed in a dry sauce.", source: "NoobCook.com" },
  "teochew::ku chye kueh": { en: "Ku chye kueh is a steamed Teochew dumpling with a translucent skin, commonly filled with savory chives and dried shrimp.", source: "Huang Kitchen" },
  "teochew::kway chap": { en: "Kway chap is a Teochew noodle soup with flat rice sheets in a dark soy sauce broth, served with braised pork offal and other ingredients.", source: "Wikipedia" },
  "teochew::lor ark (braised duck rice)": { en: "Lor ark is a traditional Teochew-style braised duck, slowly simmered in a rich, savory dark soy sauce-based gravy with various spices.", source: "TasteAtlas" },
  "teochew::mee pok dry": { en: "Mee pok dry is a Teochew noodle dish featuring flat, yellow noodles tossed in a sauce, often served with minced meat and fish balls.", source: "Wikipedia" },
  "teochew::mua chee": { en: "Mua chee is a chewy glutinous rice snack, typically coated in a mixture of ground roasted peanuts, sugar, and sesame seeds.", source: "Nyonya Cooking" },
  "teochew::orh luak (oyster omelette teochew)": { en: "Orh luak is a Teochew oyster omelette, typically pan-fried with a starchy batter and eggs, resulting in a dish with crispy edges and a gooey texture.", source: "Wikipedia" },
  "teochew::orh nee": { en: "Orh nee is a classic Teochew dessert, a silky, sweet paste made from steamed taro, often enriched with lard or coconut milk and ginkgo nuts.", source: "Fu Yuan Teochew Dining" },
  "teochew::png kueh": { en: "Png kueh is a Teochew peach-shaped dumpling with a soft, chewy skin, typically filled with savory glutinous rice, mushrooms, and dried shrimp.", source: "Huang Kitchen" },
  "teochew::sliced fish soup": { en: "Sliced fish soup is a light and nourishing broth featuring thinly sliced fish fillets, often made milky from fish bones and ginger.", source: "Nomadette" },
  "teochew::soon kueh": { en: "Soon kueh is a steamed dumpling with a translucent wrapper made from rice and tapioca flour, filled with julienned jicama and bamboo shoots.", source: "Wikipedia" },
  "teochew::teochew bak kut teh peppery": { en: "Teochew bak kut teh is a pork rib soup distinguished by its clear, peppery, and garlicky broth, contrasting with other herbal versions.", source: "Wikipedia" },
  "teochew::teochew braised duck": { en: "Teochew braised duck is a traditional dish where duck is slow-cooked in a savory braising liquid with soy sauce and aromatics like star anise.", source: "TasteAtlas" },
  "teochew::teochew fish maw soup": { en: "Teochew fish maw soup is a luxurious soup featuring rehydrated fish maw simmered in a rich broth, prized for its gelatinous texture.", source: "Food Network" },
