  "teochew::teochew porridge (mui)": { en: "Teochew porridge, or mui, is a rice porridge with distinct, whole grains, typically served with an array of accompanying side dishes.", source: "Wikipedia" },
  "teochew::teochew steamed crab": { en: "Teochew steamed crab is a dish of fresh crabs, simply steamed and served chilled to emphasize their natural sweetness and roe.", source: "Seaco Online" },
  "teochew::teochew steamed pomfret": { en: "Teochew steamed pomfret features a whole pomfret fish steamed with salted plums, preserved mustard greens, tomatoes, and ginger.", source: "What To Cook Today" },
  "teochew::teochew-style roast goose": { en: "Teochew-style roast goose is a traditional braised goose dish, prepared by simmering a whole goose in a master stock (lǔshuǐ) infused with soy sauce and spices.", source: "TasteAtlas" },
  "teochew::yusheng (lou hei)": { en: "Yusheng (Lou Hei) is a Chinese raw fish salad, traditionally tossed during Chinese New Year in Malaysia and Singapore to symbolize prosperity.", source: "Wikipedia" },
  "thai::boat noodles (kuay teow rua)": { en: "Kuay teow rua, or boat noodles, is a Thai noodle soup with a dark, intensely flavored broth traditionally thickened with pig's or beef blood.", source: "https://delishglobe.com/thai-kuay-teow-reua-boat-noodles/" },
  "thai::green curry (gaeng keow wan)": { en: "Green curry, or Gaeng Keow Wan, is a Thai curry that gets its vibrant green color from fresh green chilies in its curry paste.", source: "https://www.hotthaikitchen.com/green-curry-chicken-eggplant/" },
