  "thai::kanom buang": { en: "Kanom buang are ancient Thai crispy pancakes, filled with meringue and sweet or savory toppings like shredded coconut or foy thong.", source: "https://en.wikipedia.org/wiki/Khanom_buang" },
  "thai::khanom krok": { en: "Khanom krok are traditional Thai coconut-rice pancakes, cooked in an indented pan with two batters for a crispy shell and creamy center.", source: "https://en.wikipedia.org/wiki/Khanom_krok" },
  "thai::khao pad": { en: "Khao pad is Thai fried rice, typically made with jasmine rice, egg, garlic, and a salty element like fish sauce or soy sauce.", source: "Takeaway.com" },
