  "thai::khao soi": { en: "Khao soi is a Northern Thai noodle soup with wheat-based egg noodles in a coconut milk curry broth, often topped with crispy fried noodles.", source: "Hot Thai Kitchen" },
  "thai::larb gai": { en: "Larb gai is a Northeastern Thai meat salad with minced chicken, fresh herbs, lime juice, fish sauce, and toasted rice powder.", source: "Thai-Foodie" },
  "thai::larb moo": { en: "Larb moo is a Northeastern Thai meat salad with minced pork, fresh herbs, lime juice, fish sauce, and toasted rice powder.", source: "Cooking with Nart" },
  "thai::mango sticky rice": { en: "Mango sticky rice is a traditional Thai dessert featuring glutinous rice, fresh mango, and sweetened coconut milk.", source: "https://en.wikipedia.org/wiki/Mango_sticky_rice" },
  "thai::massaman curry": { en: "Massaman curry is a rich, mildly spicy Thai curry, known as a fusion dish combining Indian, Malay, and Persian spices with Thai ingredients.", source: "https://en.wikipedia.org/wiki/Massaman_curry" },
  "thai::moo ping": { en: "Moo ping are Thai grilled pork skewers, made from thin slices of pork marinated in a sweet, savory blend and grilled over charcoal.", source: "https://hungryinthailand.com/moo-ping-recipe/" },
  "thai::nam tok": { en: "Nam tok is a Thai meat salad with sliced grilled meat, dressed with lime juice, fish sauce, chili flakes, and toasted rice powder.", source: "Wikipedia" },
