  "thai::pad krapow moo": { en: "Pad krapow moo is a spicy Thai stir-fry of ground pork with holy basil, garlic, and Thai chilies, often served with rice.", source: "https://rachelcooksthai.com/pad-krapow-moo/" },
  "thai::pad see ew": { en: "Pad see ew is a Thai stir-fried noodle dish with wide rice noodles, soy sauce, Chinese broccoli, and meat, known for its charred, smoky flavor.", source: "https://en.wikipedia.org/wiki/Pad_see_ew" },
  "thai::pad thai": { en: "Pad Thai is a Thai stir-fried rice noodle dish, typically made with eggs, tofu, and flavored with tamarind, fish sauce, and palm sugar.", source: "https://limrosthairestaurant.com/the-history-of-pad-thai-a-complete-guide-to-thai-dishes/" },
  "thai::panang curry": { en: "Panang curry is a Thai curry known for its thick, creamy texture and mildly sweet, aromatic flavor, often featuring ground peanuts.", source: "Wikipedia" },
  "thai::red curry (gaeng phed)": { en: "Red curry, or Gaeng Phed, is a Thai dish with red curry paste cooked in coconut milk, deriving its color from dried red spur chilies.", source: "https://en.wikipedia.org/wiki/Red_curry" },
  "thai::roti gluay": { en: "Roti gluay is a Thai street food dessert, a crispy flatbread wrapped around sweet bananas and often drizzled with condensed milk.", source: "https://wanderlog.com/list/geoCategory/10392/roti-gluay-%E0%B9%82%E0%B8%A3%E0%B8%95%E0%B8%B5%E0%B8%81%E0%B8%A5%E0%B9%89%E0%B8%A7%E0%B8%A2-banana-pancake-treat" },
  "thai::som tam": { en: "Som tam is a green papaya salad from Northeastern Thailand (Isan), prepared by pounding ingredients in a mortar and pestle.", source: "MICHELIN Guide" },
