  "thai::thai chicken rice (khao man gai)": { en: "Khao man gai is Thai chicken rice featuring poached chicken and rice cooked in chicken broth and fat, served with a unique dipping sauce.", source: "https://letscooksomefood.com/khao-man-gai-thai-chicken-and-rice/" },
  "thai::thai coconut ice cream": { en: "Thai coconut ice cream is a dairy-free dessert made primarily from coconut milk, coconut cream, and sugar.", source: "https://thai-foodie.com/thai-coconut-ice-cream/" },
  "thai::thai fishcake (tod mun pla)": { en: "Tod Mun Pla are golden fried Thai fish patties made from fish paste, red curry paste, and kaffir lime leaves.", source: "https://cookrepublic.com/thai-fish-cakes-tod-mun-pla/" },
  "thai::thai milk tea (cha yen)": { en: "Cha yen is a refreshing Thai milk tea made from black tea, sweetened condensed milk, and evaporated milk, typically served iced.", source: "https://cookingwithnart.com/thai-iced-tea-recipe-cha-yen/" },
  "thai::tom kha gai": { en: "Tom kha gai is a Thai spicy and sour hot soup with coconut milk, where \"kha\" refers to galangal, a key aromatic ingredient.", source: "https://en.wikipedia.org/wiki/Tom_kha_kai" },
  "thai::tom yum goong": { en: "Tom yum goong is a Thai spicy and sour shrimp soup, characterized by hot and sour flavors from lemongrass, galangal, and kaffir lime leaves.", source: "https://en.wikipedia.org/wiki/Tom_yum_kung" },
  "vietnamese::banh khot": { en: "Bánh khọt are mini Vietnamese savory pancakes, a specialty of Vũng Tàu, made with rice flour, coconut milk, and often topped with shrimp.", source: "https://wokandkin.com/banh-khot-vietnamese-mini-savory-pancakes/" },
  "vietnamese::banh mi": { en: "Banh mi is a Vietnamese sandwich, developed in Saigon in the 1950s, featuring a crispy baguette filled with various meats, pickled vegetables, and herbs.", source: "Wikipedia" },
  "vietnamese::banh xeo": { en: "Bánh xèo is a crispy Vietnamese savory crepe, typically made with rice flour and turmeric, filled with ingredients like pork and prawns.", source: "https://en.wikipedia.org/wiki/B%C3%A1nh_x%C3%A8o" },
  "vietnamese::bo kho": { en: "Bò kho is a Vietnamese beef stew, originating in Southern Vietnam, made by simmering beef and carrots in a tomato base with aromatics like lemongrass.", source: "https://en.wikipedia.org/wiki/B%C3%B2_kho" },
  "vietnamese::bun bo hue": { en: "Bun bo Hue is a spicy Vietnamese beef noodle soup from Huế, featuring a rich broth made from simmering beef bones and pork hocks with lemongrass and shrimp paste.", source: "Hungry Huy" },
  "vietnamese::bun cha": { en: "Bun cha is a Vietnamese dish of grilled pork and noodles, thought to have originated from Hanoi, served with grilled fatty pork patties and rice vermicelli.", source: "Wikipedia" },
  "vietnamese::bun rieu": { en: "Bun rieu is a Vietnamese vermicelli noodle soup characterized by its savory crab and tomato-based broth, often including crab paste and tofu.", source: "Wikipedia" },
  "vietnamese::bun thit nuong": { en: "Bun thit nuong is a quintessential Southern Vietnamese dish of grilled pork with rice noodles, featuring marinated grilled pork over vermicelli with fresh herbs and dipping sauce.", source: "Beyond Sweet and Savory" },
  "vietnamese::ca kho to": { en: "Cá kho tộ is a Vietnamese caramelized fish dish, typically catfish, braised in a clay pot with a savory-sweet sauce.", source: "https://panningtheglobe.com/ca-kho-to-vietnamese-caramelized-braised-fish/" },
  "vietnamese::canh chua": { en: "Canh chua is a Vietnamese sour soup, often featuring fish, vegetables like pineapple and tomato, and a tamarind-based broth.", source: "Wikipedia" },
  "vietnamese::cao lau": { en: "Cao lầu is a Hoi An noodle dish featuring unique yellow noodles made with ash water from Cham Islands, served with char siu pork and fresh herbs.", source: "https://vinpearl.com/en/cao-lau-the-taste-of-hoi-an-and-vietnam-in-a-dish-1667119044" },
  "vietnamese::cha ca la vong": { en: "Chả cá Lã Vọng is a grilled fish dish from Hanoi, made with marinated hemibagrus (catfish), turmeric, and dill, often cooked tableside.", source: "https://en.wikipedia.org/wiki/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng" },
  "vietnamese::cha gio (nem ran)": { en: "Cha gio (nem ran) are Vietnamese fried spring rolls, made with a savory filling of ground pork, shrimp, and vegetables, wrapped in rice paper and deep-fried.", source: "Caroline's Cooking" },
  "vietnamese::che": { en: "Che refers to a wide variety of traditional Vietnamese sweet beverages, puddings, and desserts, often made with beans, fruit, or tapioca.", source: "Wikipedia" },
  "vietnamese::com tam": { en: "Cơm tấm is a Vietnamese dish featuring broken rice grains, traditionally served with grilled pork and various accompaniments.", source: "https://en.wikipedia.org/wiki/C%C6%A1m_t%E1%BA%A5m" },
  "vietnamese::goi cuon": { en: "Goi cuon are Vietnamese fresh spring rolls, typically filled with pork, shrimp, vermicelli noodles, and fresh herbs, all wrapped in translucent rice paper.", source: "Wikipedia" },
  "vietnamese::mi quang": { en: "Mì Quảng is a signature rice noodle dish from Quang Nam province, Central Vietnam, characterized by yellow turmeric noodles and minimal broth.", source: "https://vinpearl.com/en/mi-quang-a-must-try-delicacy-in-your-central-vietnam-tour-1675147834" },
  "vietnamese::nem nuong": { en: "Nem nuong is a Vietnamese grilled pork sausage or patty, made from seasoned ground pork and often served with rice paper or noodles.", source: "TasteAtlas" },
  "vietnamese::pho bo": { en: "Pho bo is a Vietnamese beef noodle soup with flat rice noodles in a rich, aromatic broth, traditionally simmered with beef bones and spices.", source: "" },
  "vietnamese::pho ga": { en: "Pho ga is a Vietnamese chicken noodle soup, originating in Northern Vietnam, made with a light, fragrant chicken broth and flat rice noodles.", source: "Wikipedia" },
  "vietnamese::thit kho trung": { en: "Thit kho trung is a Vietnamese braised pork belly and egg dish, simmered in a savory-sweet sauce, often with coconut water.", source: "Ta-Daa!" },
  "vietnamese::vietnamese coffee (ca phe sua da)": { en: "Ca phe sua da is Vietnamese iced coffee, made by slow-dripping strong coffee through a phin filter over sweetened condensed milk and ice.", source: "MICHELIN Guide" },
  "vietnamese::vietnamese egg coffee (ca phe trung)": { en: "Ca phe trung is a Hanoi specialty: strong Vietnamese coffee topped with a creamy foam made from whipped egg yolks and sweetened condensed milk.", source: "Silk Path Travel Guide" },
  "vietnamese::xoi": { en: "Xoi is a Vietnamese sticky rice dish, prepared by steaming glutinous rice, and can be served in both savory and sweet variations.", source: "Viet Nam National Authority of Tourism" },
